  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 105}\\
      {\fontsize{24}{30}\selectfont\color{textdark} Countries}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Represented}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} MIT}\\
      {\fontsize{24}{30}\selectfont\color{textdark} Score: 100}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Ranked No.\ 1}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 27}\\
      {\fontsize{24}{30}\selectfont\color{textdark} US in Top 100}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} North America}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.86\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 17}\\
      {\fontsize{24}{30}\selectfont\color{textdark} UK in Top 100}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} Europe}\vspace{6pt}%
    }}
  \end{minipage}
}

% -- TOP 10 TABLE --
\posterbox[
  redcard, title={Top 10 Universities Worldwide}
]{name=top10, column=1, span=3, between=row6 and row13}{
  \fontsize{34}{44}\selectfont
  \centering
  \rowcolors{1}{primary!12}{primary!5}
  \begin{tabular}{p{80pt}p{380pt}p{160pt}p{120pt}}
    \rowcolor{primary!25}
    \fontsize{30}{38}\selectfont\bfseries\color{primary}Rank &
    \fontsize{30}{38}\selectfont\bfseries\color{primary}University &
    \fontsize{30}{38}\selectfont\bfseries\color{primary}Country &
    \fontsize{30}{38}\selectfont\bfseries\color{primary}Score \\
    \fontsize{28}{36}\selectfont\bfseries\color{accent}1 &
    \fontsize{28}{36}\selectfont MIT (Massachusetts Institute of Technology) &
    \fontsize{28}{36}\selectfont United States &
    \fontsize{28}{36}\selectfont\bfseries\color{accent}100 \\
    2 &
    \fontsize{28}{36}\selectfont Imperial College London &
    \fontsize{28}{36}\selectfont United Kingdom &
    \fontsize{28}{36}\selectfont 98.5 \\
    3 &
    \fontsize{28}{36}\selectfont University of Oxford &
    \fontsize{28}{36}\selectfont United Kingdom &
    \fontsize{28}{36}\selectfont 97.9 \\
    4 &
    \fontsize{28}{36}\selectfont Harvard University &
    \fontsize{28}{36}\selectfont United States &
    \fontsize{28}{36}\selectfont 97.6 \\
    5 &
    \fontsize{28}{36}\selectfont University of Cambridge &
    \fontsize{28}{36}\selectfont United Kingdom &
    \fontsize{28}{36}\selectfont 97.0 \\
    6 &
    \fontsize{28}{36}\selectfont Stanford University &
    \fontsize{28}{36}\selectfont United States &
    \fontsize{28}{36}\selectfont 96.8 \\
    7 &
    \fontsize{28}{36}\selectfont ETH Zurich &
    \fontsize{28}{36}\selectfont Switzerland &
    \fontsize{28}{36}\selectfont 95.3 \\
    8 &
    \fontsize{28}{36}\selectfont National University of Singapore (NUS) &
    \fontsize{28}{36}\selectfont Singapore &
    \fontsize{28}{36}\selectfont 94.7 \\
    9 &
    \fontsize{28}{36}\selectfont UCL (University College London) &
    \fontsize{28}{36}\selectfont United Kingdom &
    \fontsize{28}{36}\selectfont 94.2 \\
    10 &
    \fontsize{28}{36}\selectfont California Institute of Technology (Caltech) &
    \fontsize{28}{36}\selectfont United States &
    \fontsize{28}{36}\selectfont 93.8 \\
  \end{tabular}\\[4pt]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{MIT leads with a perfect score of 100 -- a record-extending streak.}}
}

% -- METHODOLOGY --
\posterbox[
  bluecard, title={Ranking Methodology}
]{name=methodology, column=1, between=row13 and row20}{
  \fontsize{32}{42}\selectfont
  Six QS indicators drive rankings:
  \vspace{6pt}
  \begin{itemize}[itemsep=10pt]
    \item \colorbox{primary!20}{\parbox{0.85\linewidth}{\fontsize{28}{36}\selectfont\bfseries Academic Reputation \color{textgray} -- 40\%}}
    \item \colorbox{primary!20}{\parbox{0.85\linewidth}{\fontsize{28}{36}\selectfont\bfseries Citations per Faculty \color{textgray} -- 20\%}}
    \item \colorbox{primary!20}{\parbox{0.85\linewidth}{\fontsize{28}{36}\selectfont\bfseries Faculty/Student Ratio \color{textgray} -- 20\%}}
    \item \colorbox{primary!20}{\parbox{0.85\linewidth}{\fontsize{28}{36}\selectfont\bfseries Employer Reputation \color{textgray} -- 10\%}}
    \item \colorbox{primary!20}{\parbox{0.85\linewidth}{\fontsize{28}{36}\selectfont\bfseries International Faculty \color{textgray} -- 5\%}}
    \item \colorbox{primary!20}{\parbox{0.85\linewidth}{\fontsize{28}{36}\selectfont\bfseries International Students \color{textgray} -- 5\%}}
  \end{itemize}
  \vspace{4pt}
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{Based on survey of 130,000+ academics worldwide.}}
}

% -- REGIONAL BREAKDOWN --
\posterbox[
  darkcard, title={Regional Representation in Top 100}
]{name=regional, column=2, between=row13 and row20}{
  \fontsize{32}{42}\selectfont
  \centering
  \rowcolors{1}{accent!15}{accent!5}
  \begin{tabular}{p{140pt}p{100pt}}
    \rowcolor{accent!30}
    \fontsize{28}{36}\selectfont\bfseries\color{accent}Region &
    \fontsize{28}{36}\selectfont\bfseries\color{accent}Count \\
    Europe & 38 \\
    North America & 30 \\
    Asia-Pacific & 26 \\
    Middle East \& Africa & 4 \\
    Latin America & 2 \\
  \end{tabular}\\[8pt]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{Europe leads with 38 universities. US contributes 27 of North America's 30 entries.}}
}

% -- KEY TRENDS --
\posterbox[
  highlightcard, title={Key Trends for 2026}
]{name=trends, column=3, between=row13 and row20}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item \textbf{Asian universities continue to rise:} Chinese and South Korean institutions climbing significantly
    \item \textbf{UK strength persists:} 4 in top 10, 17 in top 100
    \item \textbf{Sustainability focus:} QS expands to include employer outcomes and sustainability metrics
    \item \textbf{1,500+ institutions:} Most comprehensive edition yet
  \end{itemize}
}

\end{tcbposter}
\end{document}

